 * Pre-deployment validation script
 * Confirms all required environment variables from .env.test are set
 */

const fs = require('fs');
const path = require('path');

function validateEnvironment() {
  const envTestPath = path.join(__dirname, '.env.test');

  // Check if .env.test exists
  if (!fs.existsSync(envTestPath)) {
    console.error('Error: .env.test file not found');
    process.exit(1);
  }

  // Read and parse .env.test
  const envContent = fs.readFileSync(envTestPath, 'utf-8');
  const lines = envContent.split('\n');

  const requiredKeys = [];
  const missingKeys = [];
  const emptyKeys = [];

  for (const line of lines) {
    // Skip empty lines and comments
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Extract the key (everything before the first '=')
    const equalsIndex = trimmed.indexOf('=');
    if (equalsIndex === -1) {
      continue;
    }

    const key = trimmed.substring(0, equalsIndex).trim();
    if (!key) {
      continue;
    }

    requiredKeys.push(key);

    // Check if the environment variable is set
    if (!(key in process.env)) {
      missingKeys.push(key);
    } else if (process.env[key] === '') {
      emptyKeys.push(key);
    }
  }

  // Report results
  console.log('Pre-deployment Environment Validation');
  console.log('======================================');
  console.log(`Required variables: ${requiredKeys.length}`);
  console.log(`Required: ${requiredKeys.join(', ')}`);
  console.log('');

  if (missingKeys.length > 0 || emptyKeys.length > 0) {
    if (missingKeys.length > 0) {
      console.error(`Missing environment variables (${missingKeys.length}):`);
      missingKeys.forEach((key) => console.error(`  - ${key}`));
    }

    if (emptyKeys.length > 0) {
      console.error(`Empty environment variables (${emptyKeys.length}):`);
      emptyKeys.forEach((key) => console.error(`  - ${key}`));
    }

    console.log('');
    console.error('Validation FAILED: Please set all required environment variables before deployment.');
    process.exit(1);
  }

  console.log('All required environment variables are set.');
  console.log('Validation PASSED');
  process.exit(0);
}

validateEnvironment();

