 */

const fs = require('fs');
const path = require('path');

function validateEnvironmentVariables() {
  const envTestPath = path.join(__dirname, '.env.test');

  // Check if .env.test exists
  if (!fs.existsSync(envTestPath)) {
    console.error('Error: .env.test file not found');
    process.exit(1);
  }

  const content = fs.readFileSync(envTestPath, 'utf-8');
  const lines = content.split('\n');

  const requiredVars = [];
  const missingVars = [];
  const emptyVars = [];

  // Parse .env.test to extract variable names
  for (const line of lines) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Extract variable name (everything before the first '=')
    const equalsIndex = trimmed.indexOf('=');
    if (equalsIndex > 0) {
      const varName = trimmed.substring(0, equalsIndex).trim();
      requiredVars.push(varName);
    }
  }

  // Check each required variable
  for (const varName of requiredVars) {
    const value = process.env[varName];

    if (value === undefined) {
      missingVars.push(varName);
    } else if (value === '') {
      emptyVars.push(varName);
    }
  }

  // Report results
  console.log('Pre-deployment Environment Validation');
  console.log('=====================================\n');
  console.log(`Required variables: ${requiredVars.length}`);
  console.log(`Variables checked: ${requiredVars.join(', ')}\n`);

  if (missingVars.length > 0) {
    console.error('Missing environment variables:');
    for (const varName of missingVars) {
      console.error(`  - ${varName}`);
    }
    console.error('');
  }

  if (emptyVars.length > 0) {
    console.error('Empty environment variables:');
    for (const varName of emptyVars) {
      console.error(`  - ${varName}`);
    }
    console.error('');
  }

  if (missingVars.length === 0 && emptyVars.length === 0) {
    console.log('All required environment variables are set.\n');
    console.log('Validation PASSED');
    process.exit(0);
  } else {
    console.error('Validation FAILED');
    console.error(`${missingVars.length} missing, ${emptyVars.length} empty`);
    process.exit(1);
  }
}

validateEnvironmentVariables();

