/**
 * Pre-deployment validation script
 * Reads .env.test to get the list of required environment variables
 * and confirms each one has a value set in the current environment.
 */

const fs = require('fs');
const path = require('path');

const ENV_FILE = '.env.test';

function parseEnvFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf-8');
  const requiredKeys = [];

  for (const line of content.split('\n')) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Extract the key from KEY=value format
    const match = trimmed.match(/^([A-Z_][A-Z0-9_]*)=/i);
    if (match) {
      requiredKeys.push(match[1]);
    }
  }

  return requiredKeys;
}

function validateEnvironment(requiredKeys) {
  const missing = [];
  const empty = [];

  for (const key of requiredKeys) {
    const value = process.env[key];

    if (value === undefined) {
      missing.push(key);
    } else if (value.trim() === '') {
      empty.push(key);
    }
  }

  return { missing, empty };
}

