  const envFilePath = path.resolve(process.cwd(), ENV_FILE);

  // Check if .env.test exists
  if (!fs.existsSync(envFilePath)) {
    console.error(`Error: ${ENV_FILE} not found at ${envFilePath}`);
    process.exit(1);
